<?php
function studio_form($action,$fields=[],$confirm=''){echo '<form method="post" action="studio_action.php" class="stack"'.($confirm?' data-confirm="'.e($confirm).'"':'').'>';workflow_hidden($action,$fields);}
function studio_status($s){return badge($s,in_array($s,['Approved','Transferred'],true)?'ok':($s==='Pending'?'warn':'info'));}
function studio_trail($id=0,$pid=0){$where=[];$args=[];if($id){$where[]='v.request_id=?';$args[]=$id;}if($pid){$where[]='EXISTS(SELECT 1 FROM studio_request_lines l WHERE l.request_id=v.request_id AND l.product_id=?)';$args[]=$pid;}$sql=$where?' WHERE '.implode(' AND ',$where):'';$total=(int)studio_query('SELECT COUNT(*) FROM studio_request_events v'.$sql,$args)->fetchColumn();$offset=max(0,(int)($_GET['offset']??0));echo '<section class="card"><h3>Studio History</h3><div class="table-wrap"><table class="table"><tr><th>Date / Reference</th><th>Event</th><th>Recorded By</th><th>Details / Stock Effect</th></tr>';foreach(studio_query('SELECT v.*,r.request_ref FROM studio_request_events v JOIN studio_requests r ON r.id=v.request_id'.$sql.' ORDER BY v.id DESC LIMIT 20 OFFSET '.$offset,$args) as $v){$d=json_decode($v['details_json'],true)?:[];echo '<tr><td>'.e($v['created_at']).'<br><a href="?page=studio&id='.(int)$v['request_id'].'">'.e($v['request_ref']).'</a></td><td>'.e($v['event_type']).'</td><td>'.e($v['user_name']).'<div class="muted small">'.e(role_label($v['user_role'])).'</div></td><td>';foreach(['session_reference','remarks','reason','handed_to','transfer_date','stock_effect'] as $key)if(!empty($d[$key]))echo '<div>'.e(ucwords(str_replace('_',' ',$key)).': '.$d[$key]).'</div>';foreach($d['items']??[] as $l){echo '<p>'.e($l['sku']).' · ';if(isset($l['requested']))echo 'Requested '.(int)$l['requested'].' → Approved '.(int)$l['approved'];elseif(isset($l['source_before']))echo e($l['platform']).' '.(int)$l['source_before'].' → '.(int)$l['source_after'].' · Studio '.(int)$l['studio_before'].' → '.(int)$l['studio_after'].' · Physical '.(int)$l['physical_before'].' → '.(int)$l['physical_after'];else echo (int)$l['qty'].' pcs';echo '</p>';}echo '</td></tr>';}if(!$total)echo '<tr><td colspan="4">No Studio activity.</td></tr>';echo '</table></div>'.rs8_pagination($total,$offset,20,$_GET).'</section>';}
function studio_stock_rows(){return studio_query("SELECT p.id,p.master_sku,p.name,SUM(n.qty) studio_qty FROM non_sellable n JOIN products p ON p.id=n.product_id WHERE n.condition_type='Studio Display / Demo' AND n.origin='Studio Transfer' AND EXISTS(SELECT 1 FROM studio_request_lines l WHERE l.non_sellable_id=n.id) GROUP BY p.id,p.master_sku,p.name HAVING SUM(n.qty)<>0 ORDER BY p.name")->fetchAll();}
function studio_export($type){studio_require();$heads=['Master SKU','Product','Purpose','Studio Quantity'];$rows=[];foreach(studio_stock_rows() as $p)$rows[]=[$p['master_sku'],$p['name'],'Live Session Display & Demo',(int)$p['studio_qty']];if($type==='print'){report_print_document('Studio Stocks',$heads,$rows,['As of'=>date('Y-m-d H:i:s'),'Classification'=>'Non-Sellable','Recorded by'=>current_user()['name']]);return;}if($type!=='xlsx')throw new Exception('Invalid export.');$path=tempnam(sys_get_temp_dir(),'studio-');try{report_write_xlsx($path,'Studio Stocks',$heads,$rows,['As of'=>date('Y-m-d H:i:s'),'Classification'=>'Non-Sellable']);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="Studio_Stocks.xlsx"');readfile($path);}finally{if(is_file($path))unlink($path);}}
function studio_page(){echo '<link rel="stylesheet" href="assets/studio_stocks.css?v=5.9.57"><script src="assets/studio_stocks.js?v=5.9.57" defer></script><div class="page-head"><div><h1>Studio Stocks</h1><p>Live Session Display &amp; Demo only · Non-Sellable</p></div>';if(can_action('studio_create')&&studio_ready())echo '<a class="btn primary" href="?page=studio&view=new">+ Request Stocks</a>';echo '</div>';
 if(!studio_ready()){echo '<div class="card"><h3>Enable Studio Stocks</h3><p>Adds request and history tables. Existing stocks and transactions are preserved.</p>';if(current_user()['role']==='Admin'){studio_form('studio_setup',[],'Enable Studio Stocks? Existing stocks are preserved.');echo '<button class="btn primary">Enable Studio Stocks</button></form>';}else echo '<p>Ask Admin to enable Studio Stocks.</p>';echo '</div>';return;}
 $view=$_GET['view']??'stocks';$id=(int)($_GET['id']??0);echo '<div class="tabs studio-tabs">';foreach(['stocks'=>'Studio Stocks','requests'=>'Stock Requests','history'=>'History'] as $k=>$label)echo '<a class="tab '.(!$id&&$view===$k?'active':'').'" href="?page=studio&view='.$k.'">'.$label.'</a>';echo '</div>';
 if($id){studio_detail($id);return;}if($view==='new'){studio_new_form();return;}if($view==='history'){studio_trail(0,(int)($_GET['product_id']??0));return;}
 if($view==='requests'){$total=(int)studio_query('SELECT COUNT(*) FROM studio_requests')->fetchColumn();$offset=max(0,(int)($_GET['offset']??0));echo '<section class="card"><h3>Stock Requests</h3><p class="muted small">Pending → Approved → Transferred. Approval does not deduct stock.</p><div class="table-wrap"><table class="table"><tr><th>Request / Needed Date</th><th>Requested By / Session</th><th>Requested / Approved</th><th>Status</th><th>Action</th></tr>';foreach(studio_query('SELECT r.*,u.name requester_name,(SELECT SUM(requested_qty) FROM studio_request_lines WHERE request_id=r.id) requested,(SELECT SUM(approved_qty) FROM studio_request_lines WHERE request_id=r.id) approved FROM studio_requests r LEFT JOIN users u ON u.id=r.created_by ORDER BY r.id DESC LIMIT 10 OFFSET '.$offset) as $r){$label=$r['status']==='Pending'&&can_action('studio_decide')?'Review Request':($r['status']==='Approved'&&can_action('studio_post')?'Prepare Transfer':'View Request');echo '<tr><td>'.e($r['request_ref']).'<div class="muted small">'.e($r['needed_date']).'</div></td><td>'.e($r['requester_name']).'<div class="muted small">'.e($r['session_reference']).'</div></td><td>'.(int)$r['requested'].' / '.($r['approved']===null?'—':(int)$r['approved']).' pcs</td><td>'.studio_status($r['status']).'</td><td><a class="btn ghost sm" href="?page=studio&id='.$r['id'].'">'.$label.'</a></td></tr>';}if(!$total)echo '<tr><td colspan="5">No stock requests.</td></tr>';echo '</table></div>'.rs8_pagination($total,$offset,10,$_GET).'</section>';return;}
 echo '<section class="card"><div class="card-head"><h3>Available in Studio</h3><div class="modal-actions"><a class="btn ghost sm" href="?page=studio&studio_export=xlsx">Download Excel</a><a class="btn ghost sm" href="?page=studio&studio_export=print" target="_blank" rel="noopener">Print / PDF</a></div></div><p class="muted small">Viewing only. Studio quantities cannot be reserved for orders. Display/demo sessions do not reduce stock.</p><div class="table-wrap"><table class="table"><tr><th>Product / SKU</th><th>Purpose</th><th>Studio Quantity</th><th>Action</th></tr>';$rows=studio_stock_rows();foreach($rows as $p)echo '<tr><td>'.e($p['name']).'<div class="muted small">'.e($p['master_sku']).'</div></td><td>Live Session Display &amp; Demo</td><td>'.(int)$p['studio_qty'].' pcs</td><td><a class="btn ghost sm" href="?page=studio&view=history&product_id='.$p['id'].'">View History</a></td></tr>';if(!$rows)echo '<tr><td colspan="4">No stocks transferred to Studio yet.</td></tr>';echo '</table></div></section>';}
function studio_new_form(){studio_require('studio_create');$key=bin2hex(random_bytes(32));$_SESSION['studio_request_keys'][$key]=time();$_SESSION['studio_request_keys']=array_slice($_SESSION['studio_request_keys']??[], -10,null,true);echo '<section class="card"><h3>Request Studio Stocks</h3>';studio_form('studio_create',['request_key'=>$key],'Submit this request to Operations Lead? No stock changes yet.');echo '<div class="studio-fields"><label>Needed Date<input type="date" name="needed_date" value="'.date('Y-m-d').'" required></label><label>Live Session / Demo Reference<input name="session_reference" maxlength="500" minlength="3" required placeholder="Session date, title or shoot reference"></label></div><p class="muted small">Purpose: Live Session Display &amp; Demo</p><datalist id="studio-products">';foreach(product_options() as $p)echo '<option value="'.e($p['master_sku']).'">'.e($p['name']).'</option>';echo '</datalist><div data-studio-lines><div class="studio-line" data-studio-line><label>Product / Master SKU<input name="items[0][sku]" list="studio-products" placeholder="Type SKU or select product" required autocomplete="off"></label><label>Requested Quantity<input type="number" name="items[0][qty]" min="1" max="99999999" step="1" required></label><button type="button" class="btn ghost sm" data-studio-remove aria-label="Remove item line">Remove</button></div></div><div class="modal-actions"><button type="button" class="btn secondary" data-studio-add>+ Add Item</button><button class="btn primary">Submit Request</button></div></form></section>';}
function studio_detail($id){$r=studio_request($id);$lines=studio_lines($id);echo '<section class="card"><a class="back" href="?page=studio&view=requests">← Stock Requests</a><div class="card-head"><h3>'.e($r['request_ref']).'</h3>'.studio_status($r['status']).'</div><p>Requested by '.e($r['requester_name']).' · Needed '.e($r['needed_date']).'</p><p>Live Session / Demo: '.e($r['session_reference']).'</p><p class="muted small">Purpose: Live Session Display &amp; Demo</p>';if($r['decision'])echo '<p>Decision remarks: '.e($r['decision']).'</p>';if($r['approved_at'])echo '<p class="muted small">Reviewed by '.e($r['approver_name']).' · '.e($r['approved_at']).'</p>';if($r['transferred_at'])echo '<p class="muted small">Transferred by '.e($r['transfer_name']).' · '.e($r['transferred_at']).' · Handed to '.e($r['handed_to']).'</p>';
 $decide=$r['status']==='Pending'&&can_action('studio_decide');$transfer=$r['status']==='Approved'&&can_action('studio_post');if($decide)studio_form('studio_decide',['id'=>$id,'revision'=>$r['revision']],'Save this decision? No stock will change.');elseif($transfer)studio_form('studio_preview',['id'=>$id]);echo '<div class="table-wrap"><table class="table"><tr><th>Product / SKU</th><th>Studio Now</th><th>Requested</th><th>Approved</th>'.($transfer?'<th>Source Allocation</th>':'').'</tr>';foreach($lines as $l){echo '<tr><td>'.e($l['name']).'<div class="muted small">'.e($l['master_sku']).'</div></td><td>'.studio_balance($l['product_id']).'</td><td>'.(int)$l['requested_qty'].'</td><td>'.($decide?'<input class="studio-qty" type="number" name="approved['.$l['id'].']" value="'.$l['requested_qty'].'" min="0" max="'.$l['requested_qty'].'" step="1" aria-label="Approved quantity for '.e($l['master_sku']).'" required>':($l['approved_qty']===null?'—':(int)$l['approved_qty'])).'</td>';if($transfer){echo '<td>';if((int)$l['approved_qty']>0){echo '<select name="sources['.$l['id'].']" required>';foreach(array_keys(om_shops()) as $pl)echo '<option value="'.e($pl).'">'.e($pl).' · '.om_available($l['product_id'],$pl).' available</option>';echo '</select>';}else echo 'Not approved';echo '</td>';}echo '</tr>';}echo '</table></div>';if($decide)echo '<label>Decision Remarks<input name="reason" maxlength="2000" placeholder="Required for rejection / reduced quantities"></label><div class="modal-actions"><input type="hidden" name="decision" value=""><button class="btn secondary" data-studio-decision="Reject">Reject Request</button><button class="btn primary" data-studio-decision="Approve">Approve Request</button></div></form>';elseif($transfer)echo '<p class="muted small">Only approved quantities can be transferred. Actual handover is confirmed on the next screen.</p><button class="btn primary">Review Transfer Effects</button></form>';
 $saved=$_SESSION['studio_preview'][$id]??null;if($transfer&&($_GET['step']??'')==='review'&&$saved&&$saved['user_id']===current_user()['id']){echo '<div class="studio-review"><h3>Confirm Actual Transfer</h3><div class="table-wrap"><table class="table"><tr><th>Product / SKU</th><th>Qty</th><th>Platform Stock</th><th>Studio</th><th>Total Physical</th></tr>';foreach($saved['plan']['rows'] as $l)echo '<tr><td>'.e($l['sku'].' · '.$l['name']).'</td><td>'.$l['qty'].'</td><td>'.e($l['platform']).' '.$l['source_before'].' → '.($l['source_before']-$l['qty']).'</td><td>'.$l['studio_before'].' → '.($l['studio_before']+$l['qty']).'</td><td>'.$l['physical_before'].' → '.$l['physical_before'].'</td></tr>';echo '</table></div>';studio_form('studio_post',['id'=>$id,'token'=>$saved['token']],'Post the actual transfer to Studio? Sellable stocks will decrease and Studio stocks will increase once.');echo '<p>Transfer date: '.date('Y-m-d').' · Actual posting date</p><label>Handed To<input name="handed_to" minlength="3" maxlength="120" required placeholder="Live Producer / Studio custodian name"></label><label class="ack"><input type="checkbox" name="physical_ack" value="1" required> I verified the items and physically handed over these approved quantities to Studio.</label><button class="btn primary">Confirm &amp; Transfer to Studio</button></form></div>';}
 if(in_array($r['status'],['Pending','Approved'],true)&&(current_user()['role']==='Admin'||($r['status']==='Pending'&&(int)$r['created_by']===current_user()['id']&&can_action('studio_cancel')))){echo '<details class="studio-cancel"><summary>Cancel Untransferred Request</summary>';studio_form('studio_cancel',['id'=>$id,'revision'=>$r['revision']],'Cancel this request? No stock changes.');echo '<label>Cancellation Reason<input name="reason" minlength="3" required></label><button class="btn secondary">Cancel Request</button></form></details>';}echo '</section>';studio_trail($id);}
